function esc(t){return String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function save(){if(exited)return;if(G.commandAcknowledge)G.commandAcknowledge(s);try{localStorage.setItem(KEY,JSON.stringify(s));localStorage.setItem(KEY+'-'+s.scenarioId,JSON.stringify(s));savable=true}catch(e){savable=false}$('save-status').textContent=savable?'Saved on this device · Export for a backup':'Browser storage unavailable · Use Export save to keep progress'}
