 if(!box){box=document.createElement('details');box.id='training-controls';box.className='training-controls';document.querySelector('.situation').after(box)}
 const cfg=G.scenario(s);box.hidden=!cfg.sandbox;if(!cfg.sandbox)return;
 // Preserve pending form entries and whether the panel is expanded across map selections.
 const old={x:$('training-x')?.value,y:$('training-y')?.value,side:$('training-side')?.value,type:$('training-type')?.value};
 box.innerHTML=`<summary>Command Proving Ground · Training controls</summary><p>24 × 18 fictional exercise · no victory deadline · 30 minutes per turn. Zoom + to inspect a sector, or Fit map for the whole area. Standard combat, spotting, command links and movement still apply.</p><div class="training-actions"><button data-training="replenish">Replenish air, ammunition & supplies</button><button data-training="restore" ${!selected?'disabled':''}>Restore selected unit</button><button data-training="targets">Reset original enemy positions</button><button data-training="crossings">Reset bridge damage</button></div><div class="training-options"><label><input id="training-air" type="checkbox" ${s.sandbox.unlimitedAir?'checked':''}> Renewable air missions</label><label><input id="training-stock" type="checkbox" ${s.sandbox.autoResupply?'checked':''}> Refill reserves & ammo each turn</label><label>Enemy behavior <select id="training-enemy"><option value="static">Static defense · return fire</option><option value="active">Normal maneuvering AI</option></select></label></div><p>Air strikes retain the normal one-strike-per-turn limit. Automatic refills do not repair casualties or remove fatigue. Switch them off to test supply shortages. Boundaries show estimated frontage; use Support / Reserve missions to test the current subordinate behavior.</p><div class="training-options"><label>Reinforcement side<select id="training-side"><option value="us">Friendly</option><option value="de">Enemy</option></select></label><label>Unit type<select id="training-type"><option value="infantry">Infantry battalion</option><option value="tank">Tank company</option><option value="artillery">Artillery battery</option><option value="engineers">Engineer company</option></select></label><label>Column<input id="training-x" type="number" min="1" max="24" value="24"></label><label>Row<input id="training-y" type="number" min="1" max="18" value="10"></label><button id="training-add">Request reinforcement</button></div><p>Arrival follows the next resolution at your chosen hex; occupied entries wait and retry. Pending: ${(s.sandbox.queue||[]).length}. Units including losses: ${s.units.length}/120. All normal attachment, weather, recon and staff-report controls remain available.</p><p id="training-message" role="status"></p>`;
 for(const k of ['x','y','side','type'])if(old[k]!==undefined)$('training-'+k).value=old[k];$('training-enemy').value=s.sandbox.enemyMode;
 box.querySelectorAll('[data-training]').forEach(b=>b.onclick=()=>{const error=G.sandboxAction(s,b.dataset.training,{id:selected});save();render();$('training-message').textContent=error||'Training action applied; see battle dispatches.'});
 for(const [id,key] of [['training-air','unlimitedAir'],['training-stock','autoResupply']])$(id).onchange=()=>{s.sandbox[key]=$(id).checked;if(key==='unlimitedAir'&&s.sandbox[key])s.airRemaining=99;save();render()};
