$('operations-status').innerHTML=`<p><strong>${G.operational(s)?'Operational depth active':'Operational depth off'}</strong> · ${G.bridgeList(s).length} crossings · Regimental distribution +${G.regimentalSupply(state)} supply points.</p>`+(s.scenarioId==='utah'&&s.utahEvents?`<p>Beach congestion: ${['North','Center','South'].map((name,i)=>name+' '+fields.filter(v=>v.x===8&&Math.floor(v.y/3)===i).length+' occupied hexes').join(' · ')}. Arrival timing and delays appear in dispatches.</p>`:'');
