let html=`<p class="attachment-help">Assigned support is unavailable to other formations. To transfer it, select its current formation, release it, then attach it to the new formation.</p><p class="attachment-summary"><strong>${esc(host.name)}</strong> · ${G.fieldAttachments(s,host).length}/2 field attachments · ${G.attachments(s,host).length}/2 reserve attachments</p><h3>Field units already on the map</h3><p class="attachment-help">Attach tanks and artillery to infantry. They support the host’s attack if they have no explicit order; their own range still applies. Move them separately.</p><div class="attachment-grid">${G.alive(s).filter(u=>u.side==='us'&&['tank','artillery'].includes(u.type)).map(u=>card(u,true)).join('')}</div>`;
