$('fog-toggle').onchange=()=>{s.fog=$('fog-toggle').checked;if(s.fog){for(let v of s.units){if(v.side==='us'&&v.order?.type==='attack'){let t=s.units.find(t=>t.id===v.order.target);if(!t||!G.spotted(s,t))v.order=null}}let t=s.units.find(t=>t.id===s.airTarget);if(t&&!G.spotted(s,t))s.airTarget=null}save();render()};
$('air').onclick=()=>{mode='air';render();$('hint').scrollIntoView({block:'nearest',behavior:'smooth'})};$('air-cancel').onclick=()=>{s.airTarget=null;mode='move';save();render()};
