$('move').onclick=()=>{mode='move';render()};$('attack').onclick=()=>{mode='attack';render()};$('rest').onclick=()=>{mode='move';let u=s.units.find(v=>v.id===selected);if(u){u.order=null;if(u.missionOrder)u.missionOrder.paused=true}save();render()};$('resolve').onclick=reviewCommandTurn;$('help').onclick=()=>$('manual').showModal();$('close').onclick=()=>$('manual').close();$('new').onclick=()=>{if(confirm('Start a new battle? Export your current save first if you want to keep it.')){s=G.fresh(s.scenarioId);selected=null;G.updateIntel(s);s.reports.push(G.makeReport(s));save();render();if(s.autoReport)showReport()}};
$('map-fit').onclick=fitMap;$('plus').onclick=()=>{zoom=Math.min(G.scenario(s).sandbox?5:2,zoom+.2);$('map').style.width=zoom*100+'%';$('map').style.height=zoom*100+'%'};$('minus').onclick=()=>{zoom=Math.max(1,zoom-.2);$('map').style.width=zoom*100+'%';$('map').style.height=zoom*100+'%'};
$('export').onclick=()=>{let url=URL.createObjectURL(new Blob([JSON.stringify(s,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`utah-command-${s.scenarioId}-turn-${s.turn}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)};$('import').onclick=()=>$('file').click();$('file').onchange=async e=>{let f=e.target.files[0];if(!f)return;try{if(f.size>3000000)throw Error();let p=JSON.parse(await f.text());if(p.airRemaining===undefined)p.airRemaining=3;if(p.airTarget===undefined)p.airTarget=null;G.migrate(p);if(!valid(p))throw Error();if(confirm('Replace your current battle with this saved game?')){captureSession(p.scenarioId);s=p;selected=null;save();render()}}catch(e){alert('This is not a valid Utah Command save file.')}finally{$('file').value=''}};
function readSlot(id){try{let p=JSON.parse(localStorage.getItem(KEY+'-'+id)||'null');if(p){G.migrate(p);if(valid(p))return p}}catch(e){}return null}
function openScenarios(freshStart=false){
freshStart=freshStart===true;if(!freshStart)save();
$('scenario-cards').innerHTML=G.scenarios.map(c=>{let slot=readSlot(c.id);return `<article class="scenario-card"><span class="eyebrow">${esc(c.difficulty)} · ${c.sandbox?'OPEN-ENDED · 24 × 18 MAP':c.turns+' TURNS'}</span><h3>${esc(c.name)}</h3><p>${esc(c.brief)}</p><small>${c.supply} supplies / turn · ${c.sandbox?'renewable':c.air} air missions · ${c.nation} forces</small><button class="primary" data-scenario="${c.id}">${freshStart?'Start new game':slot?'Resume · turn '+slot.turn:'Begin scenario'}</button></article>`}).join('');
$('scenario-cards').querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>{
let id=b.dataset.scenario,loaded=readSlot(id);
if(freshStart&&loaded&&!confirm('Start a new '+G.scenarios.find(c=>c.id===id).name+' game? This replaces its saved position on this device.'))return;
if(exited){
sessionSlots.clear();sessionWritable=true;
try{sessionMain=localStorage.getItem(KEY)??null;sessionView=localStorage.getItem(KEY+'-view')??null}catch(e){sessionWritable=false}
exited=false;$('exit-screen').hidden=true;document.body?.classList.toggle('game-exited',false);setMapFocus(false);
}
captureSession(id);s=freshStart?G.fresh(id):loaded||G.fresh(id);G.updateIntel(s);if(!s.reports.length)s.reports.push(G.makeReport(s));selected=null;mode='move';zoom=1;$('map').style.width='100%';$('map').style.height='100%';save();render();$('scenarios-dialog').close();if(s.autoReport)showReport()
});$('scenarios-dialog').showModal()
}
function showReport(index){
let reports=supplyView?s.supplyReports:s.reports;
if(!reports.length){G.updateIntel(s);reports.push(supplyView?G.makeSupplyReport(s,null,s.turn===1?0:s.turn-1):G.makeReport(s));save()}
if(index===undefined)index=reports.length-1;
index=Math.max(0,Math.min(index,reports.length-1));
$('report-history').innerHTML=reports.map((r,i)=>`<option value="${i}" ${i===index?'selected':''}>${r.turn===0?(supplyView?'Opening supply briefing':'Opening briefing'):'After turn '+r.turn}</option>`).join('');
let r=reports[index];$('report-title').textContent=G.scenario(s).name+(supplyView?' · SUPPLY SITREP':' · SITREP');
$('report-body').innerHTML=r.lines.map(line=>{let split=line.indexOf(' — ');return split<0?`<p>${esc(line)}</p>`:`<p><strong>${esc(line.slice(0,split))}</strong><br>${esc(line.slice(split+3))}</p>`}).join('');
$('auto-report').checked=s.autoReport;if(!$('report-dialog').open)$('report-dialog').showModal()}

$('scenarios').onclick=openScenarios;$('scenario-close').onclick=()=>$('scenarios-dialog').close();$('sitrep').onclick=()=>showReport();$('report-close').onclick=()=>$('report-dialog').close();$('report-history').onchange=()=>showReport(+$('report-history').value);$('auto-report').onchange=()=>{s.autoReport=$('auto-report').checked;save()};
function resolveBattle(decisions={}){if(exited||s.finished)return;G.resolve(s,decisions);save();render();if(s.autoReport)showReport()}
function openCommand(){renderCommandPanel();$('command-dialog').showModal()}
function renderCommandPanel(){
 $('command-enabled').checked=s.commandMode;$('command-level').value=s.commandLevel;$('support-policy').value=s.supportPolicy;
 const units=G.alive(s).filter(v=>v.side==='us'&&['infantry','tank'].includes(v.type));if(!units.some(v=>v.id===selected))selected=units[0]?.id||null;
 const u=units.find(v=>v.id===selected),m=u?.missionOrder;
 $('command-unit').innerHTML=units.map(v=>`<option value="${v.id}" ${v.id===selected?'selected':''}>${esc(v.name)}</option>`).join('');
 $('standing-mission').value=m?.type||'seize';$('mission-risk').value=m?.risk||'balanced';fillMissionGoals(m);
 $('coordinated-supporters').innerHTML=G.alive(s).filter(v=>v.side==='us'&&['infantry','tank'].includes(v.type)&&v.id!==selected).map(v=>`<label><input type="checkbox" data-coordinated="${esc(v.id)}" ${v.missionOrder?.mainEffort===selected?'checked':''}> ${esc(v.name)}</label>`).join('');
 $('mission-current').textContent=u?G.missionName(s,m)+(m?.paused?' · PAUSED':'')+' · '+(u.commandReport||'No mission report yet.'):'No operational maneuver formations.';
 $('mission-assign').disabled=!u||s.finished;$('mission-group').disabled=!u||s.finished;$('command-review-open').disabled=s.finished;$('mission-pause').disabled=!m||s.finished;$('mission-pause').textContent=m?.paused?'Resume mission':'Pause mission';$('mission-cancel').disabled=!m||s.finished;
 $('command-enabled').disabled=s.finished;$('command-level').disabled=s.finished;$('support-policy').disabled=s.finished;
 const plan=G.commandPlan(s);$('command-intentions').innerHTML=plan.proposals.map(p=>`<article class="command-card"><strong>${esc(s.units.find(v=>v.id===p.unit)?.name)}</strong><p>${esc(p.mission)}</p><p>${esc(p.report)}</p></article>`).join('')||'<p>Enable Command mode and assign a mission. Direct orders remain available.</p>';
 $('command-history').innerHTML=s.commandReports.slice(0,12).map(r=>`<p>${esc(r)}</p>`).join('')||'<p>Subordinate reports appear after each resolved turn.</p>';
}
function fillMissionGoals(m=null){const type=$('standing-mission').value,unit=selected;$('mission-goal-label').textContent=['seize','defend'].includes(type)?'Objective':'Supported formation';$('mission-goal').innerHTML=['seize','defend'].includes(type)?G.scenario(s).objectives.map((o,i)=>`<option value="${i}" ${m?.objective===i?'selected':''}>${esc(o.name)}</option>`).join(''):G.alive(s).filter(v=>v.side==='us'&&v.type!=='hq'&&v.id!==unit).map(v=>`<option value="${v.id}" ${m?.target===v.id?'selected':''}>${esc(v.name)}</option>`).join('')}
function reviewCommandTurn(force=false){const plan=G.commandPlan(s);if(!s.commandMode||!plan.proposals.length||force!==true&&!plan.requests.some(r=>!r.automatic)){resolveBattle();return}
 $('support-review-list').innerHTML=plan.requests.map(r=>{const u=s.units.find(v=>v.id===r.unit),t=s.units.find(v=>v.id===r.target),asset=s.units.find(v=>v.id===r.asset);return `<article class="command-card"><h3>${esc(u.name)} requests ${r.kind==='air'?'air support':'artillery'}</h3><p>Target: ${esc(t.name)} · ${r.kind==='air'?'fighter-bombers':esc(asset.name)}</p><p>${esc(r.reason)}</p><small>${esc(r.cost)}</small>${r.automatic?'<p class="delegated-support">Authorized automatically under your organic-support policy.</p>':`<label>Decision<select data-support-decision="${r.id}"><option value="deny">Continue without support (risk policy applies)</option><option value="approve">Approve support</option><option value="hold">Hold this formation this turn</option></select></label>`}</article>`}).join('')||'<p>No support requests this turn. No support resources have been spent.</p>';
 $('turn-intentions').innerHTML=plan.proposals.map(p=>`<article class="command-card"><strong>${esc(s.units.find(v=>v.id===p.unit)?.name)}</strong><p>${esc(p.report)}</p></article>`).join('');
 $('support-review-title').textContent='Turn '+s.turn+' · command decisions';$('support-review').showModal();
}
$('command-open').onclick=openCommand;$('command-close').onclick=()=>$('command-dialog').close();
$('command-unit').onchange=()=>{selected=$('command-unit').value;mode='move';render();renderCommandPanel()};$('standing-mission').onchange=()=>fillMissionGoals();
$('command-enabled').onchange=()=>{s.commandMode=$('command-enabled').checked;save();render();renderCommandPanel()};
$('command-level').onchange=()=>{s.commandLevel=$('command-level').value;save();render();renderCommandPanel()};$('support-policy').onchange=()=>{s.supportPolicy=$('support-policy').value;save();render();renderCommandPanel()};
$('command-review-open').onclick=()=>{$('command-dialog').close();reviewCommandTurn(true)};
$('coordinate-assign').onclick=()=>{const ids=[...$('coordinated-supporters').querySelectorAll('[data-coordinated]')].filter(e=>e.checked).map(e=>e.dataset.coordinated);const error=['seize','defend'].includes($('standing-mission').value)?G.assignCoordinatedAttack(s,selected,ids,+$('mission-goal').value,$('mission-risk').value):'Choose an objective mission above first.';if(!error){save();render();renderCommandPanel()}$('mission-message').textContent=error||'Coordinated attack assigned. Main effort and supporting elements share the objective and wait for readiness.'};
$('mission-group').onclick=()=>{const type=$('standing-mission').value,mission={type,risk:$('mission-risk').value,...(['seize','defend'].includes(type)?{objective:+$('mission-goal').value}:{target:$('mission-goal').value})};let count=0;for(const u of G.alive(s).filter(v=>v.side==='us'&&['infantry','tank'].includes(v.type))){if(['support','reserve'].includes(type)&&u.id===mission.target)continue;if(!G.assignMission(s,u.id,mission))count++}if(count){s.commandMode=true;save();render();renderCommandPanel()}$('mission-message').textContent=count+' formations received the standing mission. Disconnected formations execute standing intent locally; coordinated support needs its HQ links.'};
$('mission-assign').onclick=()=>{const type=$('standing-mission').value,mission={type,risk:$('mission-risk').value,...(['seize','defend'].includes(type)?{objective:+$('mission-goal').value}:{target:$('mission-goal').value})},error=G.assignMission(s,selected,mission);if(!error){s.commandMode=true;save();render();renderCommandPanel()}$('mission-message').textContent=error||'Mission assigned. Review its route on the map. Resolve turn pauses for support requests needing your approval.'};
$('mission-pause').onclick=()=>{const u=s.units.find(v=>v.id===selected);if(u?.missionOrder){u.missionOrder.paused=!u.missionOrder.paused;u.order=null;save();render();renderCommandPanel()}};
$('mission-cancel').onclick=()=>{const u=s.units.find(v=>v.id===selected);if(u){u.missionOrder=null;u.order=null;u.commandReport='Standing mission canceled; direct control.';save();render();renderCommandPanel()}};
$('support-review-cancel').onclick=()=>$('support-review').close();$('support-review-continue').onclick=()=>{if(!$('support-review').open||exited||s.finished)return;const choices={};$('support-review-list').querySelectorAll('[data-support-decision]').forEach(el=>choices[el.dataset.supportDecision]=el.value);$('support-review').close();resolveBattle(choices)};
const tourSteps=[
 {target:'scenarios',title:'1 · Choose an operation',text:'Start with Utah · Beach Exits. The scenario briefing explains objectives, turn limits, and victory conditions. These are original schematic scenarios, not historical orders of battle.'},
 {target:'map',title:'2 · Select and inspect',text:'Tap an Allied counter or its roster entry. Gold hexes show all destinations reachable this turn; MP means movement points. Use Fit map if you have zoomed or scrolled.'},
 {target:'move',title:'3 · Give direct orders',text:'Select Move and tap a destination, or Attack and tap a visible enemy. Orders execute when you resolve. Farther moves only cover this turn’s allowance; direct orders clear afterward.'},
 {target:'command-open',title:'4 · Delegate a mission',text:'Open Command missions. Choose a battalion, Seize or Defend an objective, and a risk policy. Missions persist, replan each turn, and show dashed cyan intentions. You can also Support a formation or remain its Reserve.'},
 {target:'resolve',title:'5 · Approve and resolve',text:'With missions active, Resolve pauses for requests needing your authority. Approve requested artillery or air support, continue without it, or hold the requester. With no pending requests, the turn resolves normally. Cancel returns to planning without advancing the turn. Attached support acts without further permission. Local artillery may be delegated; air always needs approval.'},
 {target:'sitrep',title:'6 · Read reports and protect your game',text:'Situation reports explain combat, supply, command problems, and subordinate progress. Autosave stays on this device. Export save before replacing a battle, importing a save, or moving devices. Exit without saving restores the session’s opening saves.'}
];let tourStep=0;
function renderTour(){document.querySelectorAll?.('.tour-highlight').forEach(el=>el.classList.remove?.('tour-highlight'));const t=tourSteps[tourStep];$(t.target).classList.add?.('tour-highlight');$('tour-title').textContent=t.title;$('tour-text').textContent=t.text;$('tour-back').disabled=tourStep===0;$('tour-next').textContent=tourStep===tourSteps.length-1?'Finish':'Next';$('first-game-tour').hidden=false}
function closeTour(){$('first-game-tour').hidden=true;document.querySelectorAll?.('.tour-highlight').forEach(el=>el.classList.remove?.('tour-highlight'))}
$('tour-open').onclick=()=>{setMapFocus(false);tourStep=0;renderTour()};$('tour-close').onclick=closeTour;$('tour-back').onclick=()=>{tourStep=Math.max(0,tourStep-1);renderTour()};$('tour-next').onclick=()=>{if(tourStep===tourSteps.length-1)closeTour();else{tourStep++;renderTour()}};


// Formation Intelligence: reference TO&E estimates, not simulated equipment or verified historical OB.
(function installFormationIntelligence(){
 const button=document.createElement('button');
 button.id='formation-intel-open';button.textContent='Unit composition / TO&E';
 button.title='Inspect unit echelon, personnel, tanks, and weapons';
 const heading=$('unit-title');heading.insertAdjacentElement('afterend',button);
 const dialog=document.createElement('dialog');dialog.id='formation-intel-dialog';
 dialog.style.cssText='width:min(710px,94vw);max-height:88vh;overflow:auto;border:2px solid #53634e;border-radius:12px;padding:22px;background:#faf8f1;color:#263229';
 document.body.appendChild(dialog);
 const escUnit=v=>String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
 function profile(u){
  const name=u.name.toLowerCase(),isTank=u.type==='tank',isArt=u.type==='artillery',isHQ=u.type==='hq';
  const echelon=/\b(bn|battalion)\b/i.test(u.name)||/^\d+\/\d+\s/.test(u.name)?'Battalion':/\b(company|co\.?|reserve company)\b/i.test(u.name)?'Company':/\b(det\.?|detachment)\b/i.test(u.name)?'Detachment':/\b(battery|field art|field battery)\b/i.test(u.name)?'Battery / artillery formation':/\b(section|position)\b/i.test(u.name)?'Section / fortified position':isHQ?(u.echelon||'Headquarters'):isTank?'Armored formation (echelon unspecified)':isArt?'Artillery formation (echelon unspecified)':'Infantry formation (echelon unspecified)';
  let rows,description;
  if(isHQ){rows=[['Personnel','Not specified'],['Command vehicles / radios','Not specified'],['Heavy weapons','Not specified']];description='Command headquarters; actual staff and equipment establishment not modeled.'}
  else if(isTank){rows=[['Tanks','Not specified (detachment could be smaller than a company)'],['Personnel','Not specified'],['Machine guns / small arms','Not specified'],['Recovery and maintenance vehicles','Not specified']];description='An armored detachment is not necessarily a full tank company or battalion. Do not assume a tank count from its 10 strength points.'}
  else if(isArt){rows=[['Artillery pieces','Not specified'],['Personnel','Not specified'],['Machine guns / small arms','Not specified'],['Tractors / prime movers','Not specified']];description='Gun caliber, number of tubes, and echelon require a scenario-specific establishment.'}
  else{rows=[['Personnel','Not specified'],['Rifles / carbines','Not specified'],['Automatic weapons / machine guns','Not specified'],['Mortars / anti-tank weapons','Not specified'],['Vehicles','Not specified']];description='A battalion and a company can have very different manpower and weapons. This scenario does not yet store verified equipment tables.'}
  return {echelon,rows,description};
 }
 function open(){
  const u=s.units.find(v=>v.id===selected);
  if(!u){dialog.innerHTML='<h2>Unit composition</h2><p>Select a friendly unit on the map or roster first.</p><button id="formation-intel-close">Close</button>';dialog.querySelector('#formation-intel-close').onclick=()=>dialog.close();dialog.showModal();return}
  const p=profile(u),personnel=G.personnelState(u),support=[...G.attachments(s,u).map(x=>x.name),...G.fieldAttachments(s,u).map(x=>x.name)];
  if(u.side==='us'){
   p.rows=[['Personnel (planning strength)',personnel.present+' / '+personnel.personnel],['Personnel-equivalent shortfall',personnel.shortfall],['Serviceable tanks (estimate)',personnel.serviceableTanks+' / '+personnel.tanks],['Serviceable guns (estimate)',personnel.serviceableGuns+' / '+personnel.guns],['Automatic weapons (establishment only)',personnel.automaticWeapons],['Replacement experience factor',Math.round(personnel.quality*100)+'%'],...p.rows.filter(row=>!(/Personnel|Tanks|Artillery pieces|Machine guns|automatic weapons/i).test(row[0]))];
   p.description='G-1 planning figures derive from formation type and abstract strength. Equipment estimates are not individual vehicle loss records. '+personnel.basis;
  }
  const known=u.side==='us'||!s.fog||G.spotted(s,u);
  dialog.innerHTML='<div style="display:flex;justify-content:space-between;gap:12px;align-items:center"><h2 style="margin:0">Formation Intelligence</h2><button id="formation-intel-close">Close ✕</button></div>'+
  '<h3>'+escUnit(u.name)+'</h3><p><strong>Organizational level:</strong> '+escUnit(p.echelon)+'<br><strong>Type:</strong> '+escUnit(u.type)+'<br><strong>Game strength:</strong> '+escUnit(known?u.hp+'/10':'Unknown')+' (abstract combat condition, NOT the number of vehicles or men)</p>'+
  (known?'<table style="width:100%;border-collapse:collapse">'+p.rows.map(([k,v])=>'<tr><th scope="row" style="text-align:left;border-bottom:1px solid #ddd;padding:9px">'+escUnit(k)+'</th><td style="border-bottom:1px solid #ddd;padding:9px">'+escUnit(v)+'</td></tr>').join('')+'</table>':'<p>Enemy establishment and losses are unavailable unless intelligence identifies the formation.</p>')+
  '<p>'+escUnit(p.description)+'</p>'+
  (u.side==='us'?'<p><strong>Currently assigned support:</strong> '+escUnit(support.join(', ')||'None')+'</p>':'')+
  '<p style="font-size:13px;color:#6d654e"><strong>Historical accuracy note:</strong> This is an identification and establishment reference, not a historical strength return. The present game engine tracks abstract HP, not separate personnel, tank, or weapon inventories. Exact numbers should be added only with researched TO&E and scenario-specific actual strengths.</p>';
  dialog.querySelector('#formation-intel-close').onclick=()=>dialog.close();dialog.showModal();
 }
 button.onclick=open;
})();

